const screenshotZoomControls = new WeakMap();
const screenshotPageLabels = screenshotZoomLabels[document.documentElement.lang] || screenshotZoomLabels.en;

/**
 * Toggles a screenshot between page width and a horizontally scrollable enlarged view.
 * The matching annotation markers remain attached to the image.
 * @param {Event} event Button activation from mouse, touch, or keyboard.
 */
function toggleScreenshotZoom(event) {
  const button = event.currentTarget;
  const control = screenshotZoomControls.get(button);
  const { image, viewport, message, labels } = control;

  if (!image.complete || image.naturalWidth === 0) {
    message.textContent = labels.loadError;
    return;
  }

  const expanded = button.getAttribute("aria-expanded") !== "true";
  button.setAttribute("aria-expanded", String(expanded));
  button.textContent = expanded ? labels.fit : labels.expand;
  button.setAttribute("aria-label", `${button.textContent}: ${image.alt}`);
  viewport.classList.toggle("is-expanded", expanded);

  if (expanded) {
    const width = Math.max(900, Math.min(image.naturalWidth, 1600));
    viewport.style.setProperty("--screenshot-expanded-width", `${width}px`);
    viewport.setAttribute("tabindex", "0");
    viewport.setAttribute("role", "region");
    viewport.setAttribute("aria-label", `${labels.region}: ${image.alt}`);
    message.textContent = labels.instruction;
  } else {
    viewport.scrollLeft = 0;
    viewport.style.removeProperty("--screenshot-expanded-width");
    viewport.removeAttribute("tabindex");
    viewport.removeAttribute("role");
    viewport.removeAttribute("aria-label");
    message.textContent = "";
  }
}

/**
 * Adds a keyboard-accessible zoom control to one screenshot figure.
 * @param {HTMLElement} figure Figure containing a screenshot.
 * @param {number} index Position used to associate the button and image viewport.
 */
function initializeScreenshotZoom(figure, index) {
  const image = figure.querySelector("img");
  if (!image) return;

  const imageContent = figure.querySelector(".annotated-image, .image") || image;
  const viewport = document.createElement("div");
  viewport.className = "screenshot-viewport";
  viewport.id = `mlab-screenshot-viewport-${index + 1}`;
  imageContent.before(viewport);
  viewport.appendChild(imageContent);

  const button = document.createElement("button");
  button.type = "button";
  button.className = "screenshot-zoom-button";
  button.textContent = screenshotPageLabels.expand;
  button.setAttribute("aria-label", `${screenshotPageLabels.expand}: ${image.alt}`);
  button.setAttribute("aria-expanded", "false");
  button.setAttribute("aria-controls", viewport.id);

  const message = document.createElement("p");
  message.className = "screenshot-zoom-message";
  message.setAttribute("role", "status");
  viewport.before(button, message);

  screenshotZoomControls.set(button, { image, viewport, message, labels: screenshotPageLabels });
  button.addEventListener("click", toggleScreenshotZoom);
}

document.querySelectorAll("figure").forEach(initializeScreenshotZoom);
